private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        int b = bb.get(i) & 0xFF;
        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
            i++;
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            if (bb.remaining() >= 2) {
                int value = (b1 & 0x1F) << 6 | (bb.get ( ) & 0x3F);
                sb . appendCodePoint ( value ) ;
                i += 2 ;
            } else if ((b & 0xF0) == 0xE0) {
            // Three-byte character
            if (bb.remaining() >= 3) {
                int value = (b & 0x0F) << 12 | (bb.get(i + 1) & 0x3F) << 6 | (bb.get(i + 2) & 0x3F);
                sb.appendCodePoint(value);
                i += 3;
            } else {
                break;
            }
        } else if ((b & 0xF0) == 0xF0) {
            // Four-byte character
            if (bb.remaining() >= 4) {
                int value = (b & 0x07) << 18 | (bb.get(i + 1) & 0x3F) << 12 | (bb.get(i + 2) & 0x3F) << 6 | (bb.get(i + 3) & 0x3F);
                sb.appendCodePoint(value);
                i += 4;
