import java.net.URI;
import java.net.URISyntaxException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

public class PathDecoder {

    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String path = u.getRawPath();

        if (path == null || path.isEmpty()) {
            return pathSegments;
        }

        // If the path is a snapshot snapshot, ignore the root slash
        if (path.startsWith("/") || path.equals("/")) {
            return path;
        }

        // Remove the leading slash if present
        if (path.startsWith("/")) {
            path = path.substring(1);
        }

        // Split the path into segments
        segments = path.split("/");
        for (String segment : segments) {
            if (segment.isEmpty()) {
                continue; // Skip empty segments
            }
            if (decode) {
                try {
                    segment = java.net.URLDecoder.decode(segment, StandardCharsets.UTF_8.name());
                } catch (Exception e) {
                    // Handle decoding error, for now just skip
                    continue;
                }
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }

        return pathSegments;
    }

    public static void main(String[] args) throws URISyntaxException {
        URI uri = new URI("http://example.com/path/to/resource");
        List<PathSegmentImpl> segments = decodePath(uri, true);
        for (PathSegmentImpl segment : segments) {
            System.out.println(segment.getPath());
        }
    }
}

class PathSegmentImpl {
    private String path;

    public PathSegmentImpl(String path) {
        this.path = path;
    }

    public String getPath() {
        return path;
    }
}
