public class UnescapeJava {
    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }

        StringBuilder sb = new StringBuilder();
        int len = str.length();
        int i = 0;

        while (i < len) {
            char c = str.charAt(i);
            if (c == '\\') {
                i = i + 1;
                if (i < len) {
                    char nextChar = str.charAt(i);
                    switch (nextChar) {
                        case 'b':
                            sb.append('\b');
                            break;
                        'f':
                            sb.append('\f');
                            break;
                        case 'n':
                            sb.append('\n');
                            break;
                        case 'r':
                            sb.append('\r');
                            break;
                        case 't':
                            sb.append('\t');
                            break;
                        case 'u':
                            if (i + 4 < len) {
                                String hex = str.substring(i + 1, i + 5);
                                sb.append((char) Integer.parseInt(hex, 16));
                                i += 4;
                            } else {
                                throw new Exception("Invalid Unicode escape sequence");
                            }
                            break;
                        default:
                            sb.append(nextChar);
                            break;
                    }
                    i++;
                } else {
                    sb.append(c);
                }
            } else {
                sb.append(c);
            }
            i++;
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        try {
            System.out.println(unescapeJava("Hello\\nWorld\\tThis\\u0020is\\u0020a\\u0020test"));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
