                case 12: // CONSTANT_NameAndType
                    dataInputStream.skipBytes(4);
                    break;
                case 15: // CONSTANT_MethodHandle
                    dataInputStream.skipBytes(3);
                    break;
                case 16: // CONSTANT_MethodType
                    dataInputStream.skipBytes(2);
                    break;
                case 18: // CONSTANT_InvokeDynamic
                    dataInputStream.skipBytes(4);
                    break;
                default:
                    throw new IOException("Unknown tag: " + tag);
            }
        }
        // Read the UTF8 string
        dataInputStream.skipBytes(1); // Skip tag
        int length = dataInputStream.readUnsignedShort();
        if (length > charBuffer.length) {
            throw new IllegalArgumentException("charBuffer is not large enough");
        }
        dataInputStream.readFully(charBuffer, 0, length);
        return new String(charBuffer, 0, length);
    } catch (IOException e) {
        throw new RuntimeException("Error reading UTF8 entry", e);
    }
}
