import org.jgrapht.Graph;
import org.jgrapht.GraphPath;
import org.jgrapht.graph.DefaultDirectedGraph;
import org.jgrapht.graph.DefaultEdge;
import org.jgrapht.graph.SimpleGraph;
import org.jgrapht.graph.GraphWalk;

import java.util.Set;

protected <V, E> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, new ArrayList<>(), new ArrayList<>());
    }

    V startVertex = null;
    for (E edge : tour) {
        startVertex = graph.getEdgeSource(edge);
        break;
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("Tour set is empty or graph is empty");
    }

    V currentVertex = startVertex;
    java.util.List<V> vertexList = new java.util.ArrayList<>();
    java.util.List<E> edgeList = new java.util.ArrayList<>();

    while (!tour.isEmpty()) {
        E edge = null;
        for (E e : tour) {
            if (graph.getEdgeSource(e).equals(currentVertex)) {
                edge = e;
                break;
            }
        }

        if (edge == null) {
            throw new IllegalArgumentException("Tour set does not form a valid path in the graph");
        }

        vertexList.add(currentVertex);
        edgeList.add(edge);

        currentVertex = graph.getEdgeTarget(edge);
        tour.remove(edge);
    }

    vertexList.add(currentVertex); // Add the last vertex to close the path

    return new GraphWalk<>(graph, startVertex, currentVertex, vertexList, edgeList, 0);
}
```

