import java.util.NoSuchElementException;

class ListNodeImpl<E> {
    E item;
    ListNodeImpl<E> next;
    ListNodeImpl<E> prev;

    ListNodeImpl(ListNodeImpl<E> prev, E element, ListNodeImpl<E> next) {
        this.item = element;
        this.next = next;
        this.prev = prev;
    }
}

public class LinkedListImpl<E> {
    private ListNodeImpl<E> first;
    private ListNodeImpl<E> last;
    private int size;

    private boolean unlink(Node<E> x) {
        final E element = x.item;
        final Node<E> next = x.next;
        final Node<E> prev = x.prev;

        if (prev == null) {
            first = next;
        } else {
            prev.next = next;
            x.prev = null;
        }

        if (next == null) {
            last = prev;
        } else {
            next.prev = prev;
            x.next = null;
        }

        x.item = null;
        size--;
        return element != null;
    }

    private boolean unlink(ListNodeImpl<E> node) {
        if (node == null) {
            return false;
        }
        return unlink(node);
    }

    public static void main(String[] args) {
        LinkedListImpl<String> list = new LinkedListImpl<>();
        ListNodeImpl<String> node1 = new ListNodeImpl<>(null, "one", null);
        ListNodeImpl<String> node2 = new ListNodeImpl<>(node1, "two", null);
        node1.next = node2;
        list.first = node1;
        list.last = node2;
        list.size = 2;

        boolean result = list.unlink(node1);
        System.out.println("Node removed: " + result);
        System.out.println("First node: " + list.first.item);
        System.out.println("Last node: " + list.last.item);
        System.out.println("Size: " + list.size);
    }
}
