import java.io.File;

public class FileUtils {
    public static int indexOfExtension(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastSeparator = indexOfLastSeparator(filename);
        int lastDot = filename.lastIndexOf('.');
        if (lastDot == -1 || lastSeparator > lastDot) {
            return -1;
        }
        return lastDot;
    }

    private static int indexOfLastSeparator(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastUnixPos = filename.lastIndexOf(File.separatorChar);
        int lastWindowsPos = filename.lastIndexOf('\\');
        return Math.max(lastUnixPos, lastWindowsPos);
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(indexOfExtension("file.txt")); // 4
        System.out.println(indexOfExtension("path/to/file.txt")); // 11
        System.out.println(indexOfExtension("path\\to\\file.txt")); // 11
        System.out.println(indexOfExtension("file")); // -1
        System.out.println(indexOfExtension("file.")); // 4
        System.out.println(indexOfExtension("file.name.txt")); // 8
        System.out.println(indexOfExtension(null)); // -1
    }
}
