public class SubstringMatcher {
    public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
        if (str == null || substring == null) {
            return false;
        }
        if (index < 0 || index + substring.length() > str.length()) {
            return false;
        }
        for (int i = 0; i < substring.length(); i++) {
            if (str.charAt(index + i) != substring.charAt(i)) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        // Example usage
        System.out.println(substringMatch("hello world", 6, "world")); // true
        System.out.println(substringMatch("hello world", 6, "hello")); // false
        System.out.println(substringMatch("hello world", 11, "")); // true
        System.out.println(substringMatch("hello world", 12, "a")); // false
    }
}
